108	func SeedLarge(db *sql.DB, tenant string, count int) error {
109		if tenant != "east" && tenant != "west" {
110			return fmt.Errorf("unknown tenant")
111		}
112		var existing int
113		if err := db.QueryRow(`SELECT COUNT(*) FROM certificates WHERE tenant_id=?`, tenant).Scan(&existing); err != nil {
114			return err
115		}
116		if existing > count {
117			return fmt.Errorf("tenant already has %d certificates, greater than requested %d", existing, count)
118		}
119		zone := "Australia/Sydney"
120		admin := "admin-east"
121		course := "course-east-safety"
122		if tenant == "west" {
123			zone = "Australia/Perth"
124			admin = "admin-west"
125			course = "course-west-safety"
126		}
127		loc, err := time.LoadLocation(zone)
128		if err != nil {
129			return err
130		}
131		// Stable generated IDs make interrupted runs and repeated invocations safe.
132		for start := 1; existing < count; start += 1000 {
133			ctx := context.Background()
134			conn, err := beginImmediate(ctx, db)
135			if err != nil {
136				return err
137			}
138			end := start + 999
139			for i := start; i <= end; i++ {
140				if existing >= count {
141					break
142				}
143				id := fmt.Sprintf("large-%s-%06d", tenant, i)
144				learner := "learner-" + id
145				enrollment := "enroll-" + id
146				cert := "cert-" + id
147				audit := "audit-" + id
148				name := fmt.Sprintf("Demo Learner %03d", i%250) // duplicates for search and sort checks
149				instant := time.Date(2026, 1, 10+(i%20), 13, 30, 0, 0, time.UTC)
150				utc := instant.Format(time.RFC3339)
151				local := instant.In(loc)
152				serial := fmt.Sprintf("%s-L%06d", strings.ToUpper(tenant), i)
153				if _, err = conn.ExecContext(ctx, `INSERT OR IGNORE INTO learners(id,tenant_id,name) VALUES(?,?,?)`, learner, tenant, name); err != nil {
154					break
155				}
156				if _, err = conn.ExecContext(ctx, `INSERT OR IGNORE INTO enrollments(id,tenant_id,course_id,learner_id,enrolled_at_utc,completed_at_utc) VALUES(?,?,?,?,?,?)`, enrollment, tenant, course, learner, utc, utc); err != nil {
157					break
158				}
159				var res sql.Result
160				if res, err = conn.ExecContext(ctx, `INSERT OR IGNORE INTO certificates(id,tenant_id,enrollment_id,serial_number,issued_at_utc,issued_at_local,issued_local_date,status) VALUES(?,?,?,?,?,?,?,'issued')`, cert, tenant, enrollment, serial, utc, local.Format(time.RFC3339), local.Format("2006-01-02")); err != nil {
161					break
162				}
163				if n, _ := res.RowsAffected(); n == 1 {
164					existing++
165				}
166				if _, err = conn.ExecContext(ctx, `INSERT OR IGNORE INTO audit_events(id,tenant_id,certificate_id,actor_admin_id,action,occurred_at_utc) VALUES(?,?,?,?,'issued',?)`, audit, tenant, cert, admin, utc); err != nil {
167					break
168				}
169			}
170			if err != nil {
171				conn.ExecContext(ctx, "ROLLBACK")
172				conn.Close()
173				return err
174			}
175			_, err = conn.ExecContext(ctx, "COMMIT")
176			conn.Close()
177			if err != nil {
178				return err
179			}
180		}
181		return nil
182	}

