func main() {
	path := os.Getenv("DB_PATH")
	if path == "" {
		path = "./certificates.db"
	}
	db, err := app.Open(path)
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()
	if err := app.Migrate(db); err != nil {
		log.Fatal(err)
	}
